mapper.select:
SELECT 
    a.bookset_id AS booksetId,
    a.val_date AS valDate,
    a.subject_no AS subjectNo,
    a.subject_name AS subjectName,
    a.cost AS cost,
    a.MARKET_VALUE as marketValue
FROM BOK_VAL_TABLE_DATA a
WHERE a.BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
AND a.val_date = #{valDate,jdbcType=DATE}
AND a.detail_dist = #{detailDist,jdbcType=VARCHAR}
AND a.SUBJECT_NO = #{subjectNo,jdbcType=VARCHAR}

select 
  sum(nvl(a.tdy_o_c_amt,0)) - sum(nvl(a.tdy_o_d_amt,0)) -(sum(nvl(a.tdy_o_co_c_amt,0)) - sum(nvl(a.tdy_o_co_d_amt,0)))
from BOK_BALANCE a
where a.BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
and a.balance_date = #{balanceDate,jdbcType=DATE}
and a.subject_no in ('6101', '6112')

select 
  sum(nvl(a.O_C_AMT,0)) - sum(nvl(a.O_D_AMT,0))
from BOK_BALANCE a
where a.BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
and a.balance_date = #{balanceDate,jdbcType=DATE}
and a.subject_no in ('4103', '4104')

select * from REP_PROD_INDEX
where VALUE_DATE=#{bookDate,jdbcType=DATE}
and PROD_ID=#{prodId,jdbcType=VARCHAR}

	select * from
REP_PROD_INDEX PI
LEFT JOIN REP_PROD_INFO FP ON FP.PROD_ID=PI.PROD_ID
WHERE PI.VALUE_DATE=(
